import sys, json
import z3

vocab = {
    "predicates": {
        "Eat": {"arity": 2}, "Like": {"arity": 2},
        "Big": {"arity": 1}, "Visit": {"arity": 2},
        "Cold": {"arity": 1}, "Nice": {"arity": 1},
        "Green": {"arity": 1}, "Blue": {"arity": 1},
    },
    "constants": {
        "bear": {}, "lion": {}, "mouse": {}, "squirrel": {},
    }
}

def build_env(vocab):
    env = {
        "ForAll": z3.ForAll, "Exists": z3.Exists,
        "And": z3.And, "Or": z3.Or, "Not": z3.Not,
        "Implies": z3.Implies,
        "BoolSort": z3.BoolSort, "IntSort": z3.IntSort,
        "Int": z3.Int, "Bool": z3.Bool,
        "Function": z3.Function, "Const": z3.Const,
        "True": z3.BoolVal(True), "False": z3.BoolVal(False),
    }
    for v in ("x", "y", "z", "w", "u", "v"):
        env[v] = z3.Int(v)
    for name, info in vocab.get("predicates", {}).items():
        arity = info.get("arity", 1)
        sorts = [z3.IntSort()] * arity + [z3.BoolSort()]
        env[name] = z3.Function(name, *sorts)
    for name in vocab.get("constants", {}):
        env[name] = z3.Const(name, z3.IntSort())
    return env

env = build_env(vocab)

# Test strings
test_fols = [
    ("valid_basic", "Like(mouse, bear)"),
    ("valid_forall", "ForAll([x], Implies(Eat(x, mouse), Like(x, lion)))"),
    ("backtick_wrap", "`Like(mouse, bear)`"),
    ("leading_backtick", "`ForAll([x], Implies(Green(x), Big(x)))"),
    ("markdown_bold", "**ForAll([x], Implies(Green(x), Big(x)))**"),
    ("with_colon", "Z3 expression: ForAll([x], Implies(Green(x), Big(x)))"),
    ("with_newline", "ForAll([x],\n    Implies(Green(x), Big(x)))"),
    ("first_line_trunc", "ForAll([x],"),
]

for label, fol in test_fols:
    try:
        result = eval(fol, {"__builtins__": {}}, env)
        print(f"  OK   {label}: {type(result).__name__}")
    except SyntaxError as e:
        print(f"  SYNERR {label}: {e}")
    except NameError as e:
        print(f"  NAMERR {label}: {e}")
    except Exception as e:
        print(f"  OTHER  {label}: {type(e).__name__}: {e}")
